document.querySelectorAll('[data-open]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();document.getElementById(button.dataset.open).showModal();}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
document.getElementById('quote-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.target);const viz=data.get('viz')?'3D-візуалізація: так, безкоштовно':'';const text=`Вітаю, Cutline! Хочу розрахувати вартість обклеювання.\nАвто: ${data.get('car')}\nОбсяг: ${data.get('scope')}\nКолір / фактура: ${data.get('finish')||'Потрібна консультація'}${viz?'\n'+viz:''}`;const status=event.target.querySelector('.form-status');try{await navigator.clipboard.writeText(text);status.textContent='Запит скопійовано. Його можна надіслати студії, щойно з’являться контакти.';}catch{const field=document.getElementById('request-text');field.hidden=false;field.value=text;field.select();status.textContent='Ваш запит готовий. Скопіюйте текст нижче.';}});

// Native ranges support touch dragging, keyboard arrows, Home and End.
document.querySelectorAll('.comparison input').forEach(input=>{
 const update=()=>{input.closest('.comparison').style.setProperty('--split',input.value+'%');input.setAttribute('aria-valuetext',`${input.value}% до, ${100-Number(input.value)}% після`);};
 input.addEventListener('input',update);update();
});
document.querySelectorAll('[data-film],[data-service]').forEach(button=>button.addEventListener('click',()=>{
 if(button.dataset.film)document.querySelector('[name="finish"]').value=button.dataset.film;
 if(button.dataset.service)document.querySelector('[name="scope"]').value=button.dataset.service;
}));

// Progressive enhancement: content remains visible without observers or motion.
(()=>{
 const story=document.querySelector('.studio-story'),steps=[...document.querySelectorAll('.story-step')];
 if(!story||!('IntersectionObserver' in window))return;
 story.dataset.progress='0';
 const motion=matchMedia('(prefers-reduced-motion: reduce)');
 if(!motion.matches){const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');reveal.unobserve(entry.target);}}),{threshold:.08});steps.forEach(step=>{step.classList.add('reveal-pending');reveal.observe(step);});}
 const progress=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)story.dataset.progress=String(steps.indexOf(entry.target));});},{rootMargin:'-15% 0px -40% 0px',threshold:0});steps.forEach(step=>progress.observe(step));
})();

// One open decision at a time; native buttons keep keyboard and touch behavior.
(()=>{const lab=document.querySelector('.film-lab');if(!lab)return;const buttons=[...lab.querySelectorAll('.lab-choice h3 button')],labels={style:'КОЛІР, ЯКИЙ ВІДЧУВАЄТЬСЯ',care:'ДОДАТКОВИЙ ШАР ТУРБОТИ',return:'СВОБОДА НАСТУПНОЇ ЗМІНИ'};buttons.forEach((button,index)=>{button.addEventListener('click',()=>{lab.dataset.mode=button.dataset.mode;document.getElementById('lab-material').textContent=labels[button.dataset.mode];buttons.forEach(other=>{const active=other===button;other.setAttribute('aria-expanded',String(active));other.closest('.lab-choice').classList.toggle('is-active',active);document.getElementById(other.getAttribute('aria-controls')).hidden=!active;});});button.addEventListener('keydown',event=>{let next;if(event.key==='ArrowDown')next=(index+1)%buttons.length;if(event.key==='ArrowUp')next=(index+buttons.length-1)%buttons.length;if(event.key==='Home')next=0;if(event.key==='End')next=buttons.length-1;if(next!==undefined){event.preventDefault();buttons[next].focus();}});});})();

(()=>{const buttons=[...document.querySelectorAll('[data-service-index]')],panel=document.getElementById('svc-panel');if(!panel)return;const services=[{caption:'Повне обклеювання',description:'Новий колір усього кузова. Глянець, сатин, мат або металік — під ваш характер.',scope:'Повне обклеювання'},{caption:'Окремі елементи',description:'Дах, дзеркала, капот. Контрастні деталі, які змінюють сприйняття всього автомобіля.',scope:'Окремі елементи'},{caption:'Антихром',description:'Глибокий чорний замість хромованих деталей. Чистий, стриманий образ із точними акцентами.',scope:'Антихром / індивідуальний дизайн'},{caption:'Індивідуальний дизайн',description:'Смуги, двоколірні поєднання та графіка. Створюємо композицію, що працює з лініями вашого авто.',scope:'Антихром / індивідуальний дизайн'}];let active=0;function select(index){active=index;const item=services[index];buttons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});panel.setAttribute('aria-labelledby',buttons[index].id);document.getElementById('svc-caption').textContent=item.caption;document.getElementById('svc-description').textContent=item.description;document.getElementById('svc-cta').dataset.service=item.scope;const photo=panel.querySelector('.service-photo-main');photo.style.setProperty('--photo',`${index/3*100}%`);photo.classList.remove('swapping');void photo.offsetWidth;photo.classList.add('swapping');}buttons.forEach((b,index)=>{b.addEventListener('click',()=>select(index));b.addEventListener('keydown',event=>{let next;if(event.key==='ArrowDown'||event.key==='ArrowRight')next=(active+1)%4;if(event.key==='ArrowUp'||event.key==='ArrowLeft')next=(active+3)%4;if(event.key==='Home')next=0;if(event.key==='End')next=3;if(next!==undefined){event.preventDefault();select(next);buttons[next].focus();}});});const links=[...document.querySelectorAll('.main-nav a:not([data-open])')];links.forEach(link=>link.addEventListener('click',()=>{links.forEach(other=>other.removeAttribute('aria-current'));link.setAttribute('aria-current','location');}));})();

(()=>{const root=document.querySelector('.garage');if(!root)return;const cars=[{name:'NISSAN',model:'350Z',build:'ACID LIME / CUSTOM GRAPHICS',quote:'«Пацани, це реальний роз***б!»',author:'Ростислав',owner:'Nissan 350Z · концепт',detail:'Повне обклеювання · авторська графіка · глянцевий фініш',alt:'Концепт Nissan 350Z: лаймова плівка та фіолетова графіка'},{name:'NISSAN',model:'SKYLINE',build:'ULTRA BLUE / SILVER LINES',quote:'«Тепер навіть коротка поїздка — привід озирнутися на своє авто.»',author:'Андрій',owner:'Skyline R34 · концепт',detail:'Синій металік · срібляста графіка · контрастні деталі',alt:'Концепт синього Nissan Skyline R34 зі сріблястою графікою'},{name:'MITSUBISHI',model:'EVOLUTION',build:'HYPER RED / BLACK EDITION',quote:'«Хотіла сміливий колір. Отримала характер, який видно здалеку.»',author:'Олена',owner:'Lancer Evolution IX · концепт',detail:'Червоний глянець · чорні акценти · індивідуальний дизайн',alt:'Концепт червоного Mitsubishi Evolution IX з чорною графікою'}];let current=0;const scene=root.querySelector('.garage-scene'),stage=root.querySelector('.garage-stage'),tabs=[...root.querySelectorAll('[data-garage]')];function select(index){current=(index+cars.length)%cars.length;const c=cars[current];scene.style.setProperty('--scene',current*50+'%');scene.setAttribute('aria-label',c.alt);scene.classList.remove('changing');void scene.offsetWidth;scene.classList.add('changing');document.getElementById('garage-model').replaceChildren(document.createTextNode(c.name+' '),Object.assign(document.createElement('em'),{textContent:c.model}));for(const [id,value]of Object.entries({build:c.build,quote:c.quote,author:c.author,owner:c.owner,detail:c.detail,initial:c.author[0],count:'0'+(current+1)+' / 03',live:c.owner}))document.getElementById('garage-'+id).textContent=value;tabs.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===current)));}tabs.forEach((b,i)=>b.addEventListener('click',()=>select(i)));document.getElementById('garage-prev').addEventListener('click',()=>select(current-1));document.getElementById('garage-next').addEventListener('click',()=>select(current+1));root.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();select(current+(e.key==='ArrowRight'?1:-1));}});let start=null;stage.addEventListener('touchstart',e=>{start=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});stage.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start[0],dy=e.changedTouches[0].clientY-start[1];start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4)select(current+(dx<0?1:-1));},{passive:true});stage.addEventListener('touchcancel',()=>start=null,{passive:true});})();



(()=>{const video=document.getElementById('hero-film'),play=document.getElementById('film-play'),sound=document.getElementById('film-sound'),motion=matchMedia('(prefers-reduced-motion: reduce)');let manualPause=motion.matches;const update=()=>{play.textContent=video.paused?'▶':'Ⅱ';play.setAttribute('aria-label',video.paused?'Відтворити відео':'Призупинити відео');sound.textContent=video.muted?'Увімкнути звук':'Вимкнути звук';sound.setAttribute('aria-label',sound.textContent);sound.setAttribute('aria-pressed',String(!video.muted));};const start=()=>video.play().catch(update);if(motion.matches){video.autoplay=false;video.pause();}play.onclick=()=>{manualPause=!video.paused;if(video.paused)start();else video.pause();};sound.onclick=()=>{video.muted=!video.muted;if(!video.muted){manualPause=false;start();}update();};video.addEventListener('play',update);video.addEventListener('pause',update);let inView=true;new IntersectionObserver(([entry])=>{inView=entry.isIntersecting&&entry.intersectionRatio>=.4;if(!inView)video.pause();else if(!manualPause&&!document.hidden)start();},{threshold:[0,.4]}).observe(video);document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(!manualPause&&inView)start();});motion.addEventListener('change',()=>{if(motion.matches){manualPause=true;video.pause();}});update();})();

(()=>{const intro=document.querySelector('.story-intro');if(!intro||!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;intro.classList.add('arrival-pending');const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){intro.classList.add('arrival-visible');observer.disconnect();}},{threshold:.1});observer.observe(intro);})();

(()=>{const header=document.querySelector('.header'),nav=header&&header.querySelector('.main-nav');if(!nav)return;let navTop=0,ticking=false;const measure=()=>{const pinned=header.classList.contains('nav-pinned');header.classList.remove('nav-pinned');header.style.minHeight='';navTop=nav.getBoundingClientRect().top+scrollY;if(pinned)pin(true);};const pin=on=>{if(on){header.style.minHeight=header.offsetHeight+'px';header.classList.add('nav-pinned');}else{header.classList.remove('nav-pinned');header.style.minHeight='';}};const pinTop=()=>innerWidth>900?14:10;const links=[...nav.querySelectorAll('a[href^="#"]:not([data-open])')],sections=links.map(a=>document.querySelector(a.getAttribute('href')));const update=()=>{ticking=false;const on=scrollY>navTop-pinTop();if(on!==header.classList.contains('nav-pinned'))pin(on);let current=links[0];sections.forEach((s,i)=>{if(s&&s.getBoundingClientRect().top<=innerHeight*.35)current=links[i];});links.forEach(a=>a===current?a.setAttribute('aria-current','location'):a.removeAttribute('aria-current'));};addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(update);}},{passive:true});addEventListener('resize',()=>{measure();update();});measure();update();})();

(()=>{const heads=[...document.querySelectorAll('main>section:not(.hero) h2')];if(!heads.length||!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;heads.forEach(h=>{let i=0;const walk=node=>{[...node.childNodes].forEach(c=>{if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(part=>{if(!part)return;if(/^\s+$/.test(part)){f.append(part);return;}const word=document.createElement('h-word'),inner=document.createElement('h-word-in');inner.style.setProperty('--i',i++);inner.textContent=part;word.append(inner);f.append(word);});c.replaceWith(f);}else if(c.nodeType===1&&c.tagName!=='BR')walk(c);});};walk(h);h.classList.add('split-pending');});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('split-in');observer.unobserve(e.target);}}),{threshold:.3,rootMargin:'0px 0px -8% 0px'});heads.forEach(h=>observer.observe(h));})();

(()=>{const car=document.querySelector('.viz-car');if(car&&car.pauseAnimations&&matchMedia('(prefers-reduced-motion: reduce)').matches){car.setCurrentTime(2);car.pauseAnimations();}})();
